import * as G from './b25-geometry.js';
import {inspect} from './b25-model.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(name,label,attr='')=>`<button type="button" data-x="g25-${name}" ${attr}>${esc(label)}</button>`;
const f=(name,label,value,extra='')=>`<label class="g25-field"><span>${esc(label)}</span><input data-xfield="${name}" value="${esc(value)}" ${extra}></label>`;
const select=(name,label,value,options)=>`<label class="g25-field"><span>${esc(label)}</span><select data-xfield="${name}"><option value="">选择</option>${options.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;
const qs=(t,m)=>(t.questions||[]).map((q,i)=>q.options?select('answers.'+i,q.label,m.answers[i],q.options):f('answers.'+i,q.label,m.answers[i], 'inputmode="decimal"')).join('');
const line=(a,b,attrs='')=>`<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" ${attrs}/>`;
const map=(c,r,a)=>[c[0]+r*Math.cos(G.rad(a)),c[1]-r*Math.sin(G.rad(a))];
const svg=(body,label,box='0 0 760 430')=>`<svg class="g25-svg" viewBox="${box}" role="img" aria-label="${esc(label)}">${body}</svg>`;
function sector(c,r,angle,fill='#e8bf82') {if(!angle)return'';const p=map(c,r,angle),large=angle>180?1:0;if(angle===360){const l=map(c,r,180),z=map(c,r,360);return`<path d="M ${c} L ${map(c,r,0)} A ${r} ${r} 0 0 0 ${l} A ${r} ${r} 0 0 0 ${z} Z" fill="${fill}" fill-opacity=".45" stroke="#c28c53"/>`;}return`<path d="M ${c} L ${map(c,r,0)} A ${r} ${r} 0 ${large} 0 ${p} Z" fill="${fill}" fill-opacity=".45" stroke="#c28c53"/>`;}
function turnVisual(t,b){const c=[370,226],r=[0,100,145,190][b.length],base=map(c,r,0),tip=map(c,r,b.angle);let s=sector(c,80,b.angle)+line(c,base,'stroke="#597d6b" stroke-width="7" stroke-linecap="round"')+line(c,tip,'stroke="#b97742" stroke-width="7" stroke-linecap="round"')+`<circle cx="${c[0]}" cy="${c[1]}" r="7" fill="#415d50"/>`;
 for(const record of b.records)if(record.angle!==b.angle)s+=line(c,map(c,130,record.angle),'stroke="#88a996" stroke-width="2" stroke-dasharray="6 5"');
 if(t.scene==='cross'){const p=map(c,r,180),q=map(c,r,(b.angle+180)%360);s+=line(c,p,'stroke="#597d6b" stroke-width="7" stroke-linecap="round"')+line(c,q,'stroke="#b97742" stroke-width="7" stroke-linecap="round"');}
 return svg(s,'两条线从同一点出发，橙色线实际转过 '+b.angle+' 度')+`<p class="g25-caption">当前转过 ${b.angle}°；已记下：${b.records.map(x=>x.angle+'°').join('、')||'还没有'}。</p>`;}
function smallAngle(c,angle,r,color='#b97742'){return sector(c,25,angle,'#e5d7b9')+line(c,map(c,r,0),'stroke="#5b7d6c" stroke-width="4"')+line(c,map(c,r,angle),`stroke="${color}" stroke-width="4"`)+`<circle cx="${c[0]}" cy="${c[1]}" r="4" fill="#425e50"/>`;}
function compareVisual(t,b){let s='';t.angles.forEach((a,i)=>{const c=[105+i*175,185],r=48+18*(t.lengths?.[i]||1);s+=`<rect x="${c[0]-90}" y="55" width="165" height="225" rx="12" fill="${b.selected.includes(i)?'#e4efdf':'#f8f8f1'}" stroke="#b5c7b9"/>`+smallAngle(c,a,r)+`<text x="${c[0]}" y="260" text-anchor="middle">图${i+1}${b.selected.includes(i)?' · 已选':''}</text>`;});if(b.last!==null){s+=`<text x="380" y="320" text-anchor="middle">图${b.last+1}与直角叠在一起比较</text>`;const c=[380,400];s+=line(c,map(c,65,90),'stroke="#90a995" stroke-width="3" stroke-dasharray="6 4"')+smallAngle(c,t.angles[b.last],75);}return svg(s,'不同开口的角，边的长度不相同','0 0 760 510');}
function protractorVisual(t,b){const c=[380,300],o=[c[0]+b.x,c[1]+b.y],r=225;let s=line(c,map(c,245,0),'stroke="#547e69" stroke-width="6"')+`<circle cx="${c[0]}" cy="${c[1]}" r="5" fill="#3e6250"/>`;const amount=t.mode==='measure'?t.amount:b.drawn;if(amount!==null)s+=sector(c,70,amount)+line(c,map(c,245,amount),'stroke="#b77843" stroke-width="6"');
 let tool=`<path d="M ${o[0]-r} ${o[1]} A ${r} ${r} 0 0 1 ${o[0]+r} ${o[1]} L ${o[0]-r} ${o[1]}" fill="#d9e7dc" fill-opacity=".55" stroke="#789682" stroke-width="2"/>`;
 for(let d=0;d<=180;d++){const a=map(o,r,d),z=map(o,r-(d%10===0?14:d%5===0?9:4),d);tool+=line(a,z,'stroke="#678675" stroke-width="1.5"');if(d%10===0){const p=map(o,r-28,d),q=map(o,r-62,d);tool+=`<text class="g25-scale" x="${p[0]}" y="${p[1]+4}" text-anchor="middle" font-size="12">${d}</text><text class="g25-scale g25-scale-inner" x="${q[0]}" y="${q[1]+4}" text-anchor="middle" font-size="11" fill="#a36d41">${180-d}</text>`;}}
 tool+=line([o[0]-10,o[1]],[o[0]+10,o[1]],'stroke="#4f7561" stroke-width="2"')+line([o[0],o[1]-10],[o[0],o[1]+10],'stroke="#4f7561" stroke-width="2"');s+=`<g transform="rotate(${b.rotation} ${o[0]} ${o[1]})">${tool}</g>`;
 return svg(s,'移动和翻转的半圆量角器覆盖在角的两条边上','0 0 760 600')+`<p class="g25-caption">先让中心对准顶点，再让基线的0°对准绿色边。</p>`;}
function ticksVisual(b){const ps=[[150,100],[570,100],[570,310],[150,310]];let s=`<polygon points="${ps.map(p=>p.join(',')).join(' ')}" fill="#deebdf" stroke="#648672" stroke-width="4"/>`;for(let i=0;i<4;i++){const a=ps[i],c=ps[(i+1)%4],dx=c[0]-a[0],dy=c[1]-a[1],len=Math.hypot(dx,dy),ux=dx/len,uy=dy/len,vx=-uy,vy=ux,mid=[(a[0]+c[0])/2,(a[1]+c[1])/2];for(let j=0;j<b.marks[i];j++){const offset=(j-(b.marks[i]-1)/2)*10,x=mid[0]+ux*offset,y=mid[1]+uy*offset;s+=line([x-vx*10,y-vy*10],[x+vx*10,y+vy*10],'stroke="#b57343" stroke-width="4"');}s+=`<text x="${mid[0]+vx*22}" y="${mid[1]+vy*22}" text-anchor="middle">边${i+1}</text>`;}return svg(s,'点击图形边的按钮，为两对等长边画不同的刻痕');}
function similarVisual(t,b){const p=G.asa(3,50,60),mapped=(origin,scale)=>p.map(q=>[origin[0]+q[0]*scale,origin[1]-q[1]*scale]);const a=mapped([100,350],45),c=mapped([400,350],45*b.scale);return svg(`<polygon points="${a.map(p=>p.join(',')).join(' ')}" fill="#bdd8c5" stroke="#5c846d" stroke-width="3"/><polygon points="${c.map(p=>p.join(',')).join(' ')}" fill="#ead0a5" stroke="#b57d48" stroke-width="3"/><text x="100" y="382">第一块：角50°、60°、70°</text><text x="400" y="382">第二块：同样的角，边长是 ${b.scale} 倍</text>`,'两个三角形保持相同角度而改变大小');}
function cornersVisual(t,b){const src=G.asa(5,t.a,t.b),to=p=>[90+p[0]*47,330-p[1]*47],ps=src.map(to),angles=G.triangleAngles(src),colors=['#d3ad83','#a5cbb3','#9fb8d1'],center=[570,315];let s=`<polygon points="${ps.map(p=>p.join(',')).join(' ')}" fill="#e2ecde" stroke="#5a806c" stroke-width="4"/>`;ps.forEach((p,i)=>s+=`<circle cx="${p[0]}" cy="${p[1]}" r="11" fill="${b.selected.includes(i)?colors[i]:'#fff'}" stroke="#547963" stroke-width="3"/><text x="${p[0]+12}" y="${p[1]-8}">${String.fromCharCode(65+i)}</text>`);let start=0;angles.forEach((a,i)=>{if(b.selected.includes(i))s+=`<g transform="rotate(${-start} ${center[0]} ${center[1]})">${sector(center,110,a,colors[i])}</g>`;start+=a;});s+=line(center,map(center,125,0),'stroke="#6b8974" stroke-width="3"')+line(center,map(center,125,180),'stroke="#6b8974" stroke-width="3"');return svg(s,'把三角形三个角按真实大小移到一条直线上比较');}
function verticesVisual(t,b){const m=p=>[160+p[0]*70,370-p[1]*70],ps=t.points.map(m);let s=`<polygon points="${ps.map(p=>p.join(',')).join(' ')}" fill="#d9e9dc" stroke="#5a806c" stroke-width="4"/>`;ps.forEach((p,i)=>{if(t.kind==='right'&&b.selected.includes(i)){const prev=ps[(i+ps.length-1)%ps.length],next=ps[(i+1)%ps.length],u=[prev[0]-p[0],prev[1]-p[1]],v=[next[0]-p[0],next[1]-p[1]],du=Math.hypot(...u),dv=Math.hypot(...v),a=[p[0]+u[0]*18/du,p[1]+u[1]*18/du],c=[p[0]+v[0]*18/dv,p[1]+v[1]*18/dv],mid=[a[0]+v[0]*18/dv,a[1]+v[1]*18/dv];s+=`<path d="M ${a} L ${mid} L ${c}" fill="none" stroke="#b57343" stroke-width="3"/>`;}s+=`<circle cx="${p[0]}" cy="${p[1]}" r="11" fill="${b.selected.includes(i)?'#bd7d47':'#fff'}" stroke="#547963" stroke-width="3" role="button" tabindex="0" aria-label="标记角${i+1}" data-x="g25-choose" data-index="${i}"/><text x="${p[0]+14}" y="${p[1]-8}">${String.fromCharCode(65+i)}</text>`;});return svg(s,'点击图形上的顶点，标出指定的角');}
function estimateVisual(t,b){const c=[365,280],angle=t.amount;let s=sector(c,65,angle)+line(c,map(c,195,0),'stroke="#597d6b" stroke-width="7"')+line(c,map(c,195,angle),'stroke="#b97742" stroke-width="7"')+`<circle cx="${c[0]}" cy="${c[1]}" r="6" fill="#405f50"/>`;if(b.revealed)s+=`<text x="365" y="390" text-anchor="middle">量一量：${angle}°；你的估计：${b.guess}°</text>`;return svg(s,'先估计两条射线的开口，留下估计后才显示测量结果');}
function polygonVisual(t,b){const c=[375,220],points=G.polygon(t.n).map(([x,y])=>[c[0]+x*155,c[1]-y*155]),xy=p=>p.join(',');let s=`<polygon points="${points.map(xy).join(' ')}" fill="#d8e9dc" stroke="#577d69" stroke-width="4"/>`;for(const i of b.diagonals)s+=line(points[0],points[i],'stroke="#b97742" stroke-width="3"');points.forEach((p,i)=>{s+=`<circle cx="${p[0]}" cy="${p[1]}" r="7" fill="${i===0?'#b97742':'#587c68'}"/><text x="${p[0]+12}" y="${p[1]-8}">${i===0?'起点':i+1}</text>`;});return svg(s,`${t.n}边形，从一个顶点向其他不相邻顶点连线`)+`<p class="g25-caption">已连 ${b.diagonals.length} 条线；图形分成 ${b.diagonals.length+1} 块。</p>`;}
function triangleVisual(t,b){const origin=[220,350],scale=42,point=p=>[origin[0]+p[0]*scale,origin[1]-p[1]*scale],A=point([0,0]),B=point([b.base||7,0]);let s='';
 if(b.base){s+=line(A,B,'stroke="#537a65" stroke-width="5"')+`<circle cx="${A[0]}" cy="${A[1]}" r="5"/><circle cx="${B[0]}" cy="${B[1]}" r="5"/><text x="${A[0]-16}" y="${A[1]+25}">A</text><text x="${B[0]+7}" y="${B[1]+25}">B</text><text x="${(A[0]+B[0])/2}" y="${A[1]+28}" text-anchor="middle">${b.base} cm</text>`;}
 if(t.mode==='sss'&&b.a)s+=`<circle cx="${A[0]}" cy="${A[1]}" r="${b.a*scale}" fill="none" stroke="#b57b48" stroke-width="2" stroke-dasharray="6 5"/>`;
 if((t.mode==='sss'||t.mode==='ssa')&&b.b&&b.base)s+=`<circle cx="${B[0]}" cy="${B[1]}" r="${b.b*scale}" fill="none" stroke="#7a95b2" stroke-width="2" stroke-dasharray="6 5"/>`;
 if(['ssa','sas','asa'].includes(t.mode)&&b.angle){const ray=point(G.pt([0,0],9,b.angle));s+=line(A,ray,'stroke="#bf8a57" stroke-width="2" stroke-dasharray="5 4"')+`<text x="${A[0]+38}" y="${A[1]-12}">${b.angle}°</text>`;}
 if(t.mode==='asa'&&b.other&&b.base){const ray=point(G.pt([b.base,0],9,180-b.other));s+=line(B,ray,'stroke="#7a95b2" stroke-width="2" stroke-dasharray="5 4"')+`<text x="${B[0]-48}" y="${B[1]-12}">${b.other}°</text>`;}
 for(const i of b.chosen){const p=point(b.points[i]);s+=`<polygon points="${A} ${B} ${p}" fill="${i?'#e8cba4':'#b5d5c0'}" fill-opacity=".48" stroke="${i?'#b97742':'#5b8a70'}" stroke-width="4"/>`;}
 if(b.constructed)b.points.forEach((v,i)=>{const p=point(v);s+=`<circle cx="${p[0]}" cy="${p[1]}" r="10" fill="#fff" stroke="#a66b3f" stroke-width="3" role="button" tabindex="0" aria-label="选交点${i+1}" data-x="g25-choose" data-index="${i}"/><text x="${p[0]+12}" y="${p[1]-10}">交点${i+1}</text>`;});
 if(b.constructed&&!b.points.length)s+=`<text x="440" y="70" text-anchor="middle">目前没有交点</text>`;
 return svg(s,'根据输入的长度和角度画出直线、圆弧及其实际交点','0 0 900 650');}
function parallelVisual(b){const top=[340,125],bottom=[340-170/Math.tan(G.rad(70)),295],v=[top[0]-bottom[0],-170],extend=1.38;let s=line([80,125],[680,125],'stroke="#597d6b" stroke-width="5"')+line([80,295],[680,295],'stroke="#597d6b" stroke-width="5"')+line([bottom[0]-v[0]*(extend-1),bottom[1]-v[1]*(extend-1)],[top[0]+v[0]*(extend-1),top[1]+v[1]*(extend-1)],'stroke="#bd8050" stroke-width="5"');const label=(p,ls)=>`<text x="${p[0]+25}" y="${p[1]-14}">${ls[0]}</text><text x="${p[0]-40}" y="${p[1]-14}">${ls[1]}</text><text x="${p[0]-38}" y="${p[1]+28}">${ls[2]}</text><text x="${p[0]+25}" y="${p[1]+28}">${ls[3]}</text>`;s+=label(top,['A','B','C','D'])+label(bottom,['E','F','G','H']);if(b.slid){const L=130,u=[L*Math.cos(G.rad(70)),-L*Math.sin(G.rad(70))];s+=line([bottom[0]-L,bottom[1]],[bottom[0]+L,bottom[1]],'stroke="#8badc0" stroke-width="10" stroke-opacity=".42"')+line([bottom[0]-u[0],bottom[1]-u[1]],[bottom[0]+u[0],bottom[1]+u[1]],'stroke="#e1a34d" stroke-width="10" stroke-opacity=".48"')+`<circle cx="${bottom[0]}" cy="${bottom[1]}" r="12" fill="none" stroke="#ae773e" stroke-width="2"/>`; }return svg(s,'两条平行线被一条斜线截开，上方交点的整组角可以平移到下方');}
export function visual(t,m){let v='';if(t.type==='x-g25-turn')v=turnVisual(t,m.board);if(t.type==='x-g25-compare')v=compareVisual(t,m.board);if(t.type==='x-g25-protractor')v=protractorVisual(t,m.board);if(t.type==='x-g25-polygon')v=polygonVisual(t,m.board);if(t.type==='x-g25-triangle')v=triangleVisual(t,m.board);if(t.type==='x-g25-parallel')v=parallelVisual(m.board);if(t.type==='x-g25-estimate')v=estimateVisual(t,m.board);if(t.type==='x-g25-vertices')v=verticesVisual(t,m.board);if(t.type==='x-g25-corners')v=cornersVisual(t,m.board);if(t.type==='x-g25-similar')v=similarVisual(t,m.board);if(t.type==='x-g25-ticks')v=ticksVisual(m.board);return`<div class="g25-world">${v}</div>`;}
export function controls(t,m){const b=m.board;let v='',ready=false;
 if(t.type==='x-g25-turn'){v=f('angle','转过多少度',m.angle,'inputmode="numeric"')+btn('set','按度数转')+btn('quarter','再转四分之一圈')+select('length','改变边的长短',m.length,[['1','短'],['2','中'],['3','长']])+btn('length','换边长')+btn('record','记下这次');ready=t.targets.every(a=>b.records.some(r=>r.angle===a))&&(!t.compareLengths||[1,3].every(length=>b.records.some(r=>r.angle===t.targets[0]&&r.length===length)));}
 if(t.type==='x-g25-compare'){v=`<div class="g25-buttons">${t.angles.map((_,i)=>btn('test','叠放图'+(i+1)+(b.tested.includes(i)?' ✓':''),`data-index="${i}"`)).join('')}</div><div class="g25-buttons">${t.angles.map((_,i)=>btn('choose',(b.selected.includes(i)?'✓ ':'')+'选图'+(i+1),`data-index="${i}"`)).join('')}${t.order?btn('undo','退回一个'):''}</div>`;if(t.order)v+=`<p class="g25-caption">选择顺序：${b.selected.map(i=>'图'+(i+1)).join(' → ')||'还没有选择'}</p>`;ready=b.selected.length>0;}
 if(t.type==='x-g25-protractor'){v=`<div class="g25-buttons">${['left','right','up','down'].map((d,i)=>btn('move',['← 左移','→ 右移','↑ 上移','↓ 下移'][i],`data-index="${d}"`)).join('')}${btn('flip','翻转量角器')}</div>`;if(t.mode==='draw')v+=f('angle','画多少度',m.angle,'inputmode="numeric"')+btn('draw','画这条边');ready=b.x===0&&b.y===0&&b.rotation===0&&(t.mode==='measure'||b.drawn!==null);}
 if(t.type==='x-g25-polygon'){v=`<div class="g25-buttons">${Array.from({length:t.n-3},(_,i)=>btn('diagonal',(b.diagonals.includes(i+2)?'✓ ':'')+'连接顶点'+(i+3),`data-index="${i+2}"`)).join('')}</div>`;ready=b.diagonals.length===t.n-3;}
 if(t.type==='x-g25-ticks'){v=`<div class="g25-buttons">${[0,1,2,3].map(i=>btn('markSide','边'+(i+1)+' · '+b.marks[i]+'条刻痕',`data-index="${i}"`)).join('')}</div>`;ready=b.marks.every(x=>x>0);}
 if(t.type==='x-g25-similar'){v=select('length','第二块边长倍数',m.length,[['0.5','一半'],['1','一样大'],['2','两倍'],['3','三倍']])+btn('length','改变大小');ready=b.scale!==1;}
 if(t.type==='x-g25-corners'){v=`<div class="g25-buttons">${[0,1,2].map(i=>btn('choose',(b.selected.includes(i)?'✓ ':'')+'搬来角'+String.fromCharCode(65+i),`data-index="${i}"`)).join('')}</div>`;ready=b.selected.length===3;}
 if(t.type==='x-g25-vertices'){v=`<div class="g25-buttons">${t.points.map((_,i)=>btn('choose',(b.selected.includes(i)?'✓ ':'')+'标记角'+String.fromCharCode(65+i),`data-index="${i}"`)).join('')}</div>`;ready=b.selected.length>0;}
 if(t.type==='x-g25-estimate'){v=f('angle','先估多少度',m.angle,'inputmode="numeric"')+btn('guess','留下估计')+(b.guess!==null?btn('reveal','量一量'):'' );ready=b.revealed;}
 if(t.type==='x-g25-parallel'){v=btn('slide',b.slid?'把上面的角移回':'把上面的角移到下面');ready=b.slid;}
 if(t.type==='x-g25-triangle'){const fields=[['base','画底边长度'],...(t.mode==='sss'||t.mode==='sas'?[['a',t.mode==='sss'?'从A点画圆的半径':'从A点出发的边长']]:[]),...(t.mode==='sss'||t.mode==='ssa'?[['b','从B点画圆的半径']]:[]),...(['sas','ssa','asa'].includes(t.mode)?[['angle','A处的角度']]:[]),...(t.mode==='asa'?[['other','B处的角度']]:[])];v=fields.map(([k,label])=>f(k,label,m[k],'inputmode="decimal"')+btn(k,k==='a'&&t.mode==='sss'||k==='b'?'画这一圈':k==='angle'||k==='other'?'放这条射线':'放这条边')).join('')+btn('construct','找交点');if(b.constructed){v+=`<div class="g25-buttons">${b.points.map((_,i)=>btn('choose',(b.chosen.includes(i)?'✓ ':'')+'选交点'+(i+1),`data-index="${i}"`)).join('')}</div>`+btn('finish','检查围成的图形');}ready=b.finished;}
 if(ready)v+=qs(t,m);if(m.issue)v+=`<p class="g25-issue" role="status">${esc(m.issue)}</p>`;
 if(inspect(t,m).correct)v=`<details class="g25-fold"><summary>查看或修改刚才的操作</summary>${v}</details>`;
 v+=`<details class="g25-fold"><summary>用自己的话留下发现（可选）</summary>${f('prose','我的解释或新问题',m.prose)}<small>原话会保存，暂不自动判断这段解释。</small></details>`;return`<div class="g25-controls">${v}</div>`;
}
export const render=(t,m)=>`<div id="extra-visual">${visual(t,m)}</div><div id="extra-controls">${controls(t,m)}</div>`;
